import atcoder/extra/monoid/monoid
import atcoder/extra/structure/offline_rectangle_add_rectangle_sum

const
  Modulus =
    1000000007'u64

  RandomScenarioCount =
    1024

  RandomQueryCount =
    16384

  BoundaryScenarioCount =
    128

  BoundaryQueryCount =
    1024

  DirectedScenarioCount =
    64

  DirectedQueryCount =
    512

  WideScenarioCount =
    64

  WideQueryCount =
    512

  TotalQueryCount =
    18432

  OracleSha =
    "d9d94f4de4f9a786ab3c4373b41f1f0091b136658e4bb212d995eb7687c8a612"

  Multiplier =
    6364136223846793005'u64

  Increment =
    1442695040888963407'u64

proc modAdd(
    a,
    b:
      uint64
): uint64 =
  let sum =
    a + b

  if sum >= Modulus:
    sum - Modulus
  else:
    sum

proc modZero():
    uint64 =
  0'u64

proc modInverse(
    value:
      uint64
): uint64 =
  if value == 0'u64:
    0'u64
  else:
    Modulus - value

type
  ModGroup =
    CommutativeGroupOf(
      uint64,
      modAdd,
      modZero,
      modInverse,
    )

  Rectangle =
    tuple[
      xLeft, xRight, yLower, yUpper:
        int
    ]

  InitialRectangle =
    tuple[
      xLeft, xRight, yLower, yUpper:
        int,
      weight:
        uint64
    ]

proc signedToMod(
    value:
      int
): uint64 =
  if value >= 0:
    uint64(
      value
    ) mod Modulus
  else:
    let magnitude =
      uint64(
        -value
      ) mod Modulus

    if magnitude == 0'u64:
      0'u64
    else:
      Modulus - magnitude

proc nextU64(
    state:
      var uint64
): uint64 =
  state =
    state * Multiplier +
      Increment

  state

proc nextInt(
    state:
      var uint64,
    bound:
      int
): int =
  int(
    state.nextU64() mod
      uint64(
        bound
      )
  )

proc sortedRectangle(
    x0,
    x1,
    y0,
    y1:
      int
): Rectangle =
  if x0 <= x1:
    result.xLeft =
      x0
    result.xRight =
      x1
  else:
    result.xLeft =
      x1
    result.xRight =
      x0

  if y0 <= y1:
    result.yLower =
      y0
    result.yUpper =
      y1
  else:
    result.yLower =
      y1
    result.yUpper =
      y0

proc nextSmallRectangle(
    state:
      var uint64
): Rectangle =
  sortedRectangle(
    state.nextInt(17) - 8,
    state.nextInt(17) - 8,
    state.nextInt(17) - 8,
    state.nextInt(17) - 8,
  )

proc nextPoolRectangle(
    state:
      var uint64,
    coordinates:
      openArray[
        int
      ]
): Rectangle =
  sortedRectangle(
    coordinates[
      state.nextInt(
        coordinates.len
      )
    ],
    coordinates[
      state.nextInt(
        coordinates.len
      )
    ],
    coordinates[
      state.nextInt(
        coordinates.len
      )
    ],
    coordinates[
      state.nextInt(
        coordinates.len
      )
    ],
  )

