proc checkAnswers(
    answers:
      seq[
        uint64
      ],
    expectedOffset,
    expectedCount:
      int
) =
  doAssert answers.len ==
    expectedCount

  for index in 0 ..<
      expectedCount:
    doAssert answers[
      index
    ] == OracleExpected[
      expectedOffset + index
    ]

block deterministicRandomDifferential:
  var state =
    20260808'u64

  for scenarioIndex in 0 ..<
      RandomScenarioCount:
    let initialCount =
      state.nextInt(8)

    var initialRectangles =
      newSeq[
        InitialRectangle
      ]()

    for initialIndex in 0 ..<
        initialCount:
      let rectangle =
        state.nextSmallRectangle()

      let weight =
        signedToMod(
          state.nextInt(31) - 15
        )

      initialRectangles.add(
        (
          xLeft:
            rectangle.xLeft,
          xRight:
            rectangle.xRight,
          yLower:
            rectangle.yLower,
          yUpper:
            rectangle.yUpper,
          weight:
            weight,
        )
      )

    var solver =
      initOfflineRectangleAddRectangleSum[
        ModGroup
      ](
        initialRectangles,
        ModGroup,
      )

    for pairIndex in 0 ..<
        16:
      let queryFirst =
        state.nextInt(2) == 0

      let queryRectangle =
        state.nextSmallRectangle()

      let updateRectangle =
        state.nextSmallRectangle()

      let updateWeight =
        signedToMod(
          state.nextInt(31) - 15
        )

      if queryFirst:
        doAssert solver.addRectangleQuery(
          queryRectangle.xLeft,
          queryRectangle.xRight,
          queryRectangle.yLower,
          queryRectangle.yUpper,
        ) == pairIndex

        solver.addRectangle(
          updateRectangle.xLeft,
          updateRectangle.xRight,
          updateRectangle.yLower,
          updateRectangle.yUpper,
          updateWeight,
        )
      else:
        solver.addRectangle(
          updateRectangle.xLeft,
          updateRectangle.xRight,
          updateRectangle.yLower,
          updateRectangle.yUpper,
          updateWeight,
        )

        doAssert solver.addRectangleQuery(
          queryRectangle.xLeft,
          queryRectangle.xRight,
          queryRectangle.yLower,
          queryRectangle.yUpper,
        ) == pairIndex

    doAssert solver.queryCount() ==
      16

    let answers =
      solver.solve()

    checkAnswers(
      answers,
      scenarioIndex * 16,
      16,
    )

block deterministicBoundaryDifferential:
  let coordinates = [
    low(int),
    low(int) + 1,
    low(int) + 2,
    -2,
    -1,
    0,
    1,
    2,
    high(int) - 2,
    high(int) - 1,
    high(int),
  ]

  var state =
    20260809'u64

  for scenarioIndex in 0 ..<
      BoundaryScenarioCount:
    var initialRectangles =
      newSeq[
        InitialRectangle
      ]()

    for initialIndex in 0 ..<
        4:
      let rectangle =
        state.nextPoolRectangle(
          coordinates
        )

      initialRectangles.add(
        (
          xLeft:
            rectangle.xLeft,
          xRight:
            rectangle.xRight,
          yLower:
            rectangle.yLower,
          yUpper:
            rectangle.yUpper,
          weight:
            signedToMod(
              state.nextInt(23) - 11
            ),
        )
      )

    var solver =
      initOfflineRectangleAddRectangleSum[
        ModGroup
      ](
        initialRectangles,
        ModGroup,
      )

    for pairIndex in 0 ..<
        8:
      let queryFirst =
        state.nextInt(2) == 0

      let queryRectangle =
        state.nextPoolRectangle(
          coordinates
        )

      let updateRectangle =
        state.nextPoolRectangle(
          coordinates
        )

      let updateWeight =
        signedToMod(
          state.nextInt(23) - 11
        )

      if queryFirst:
        doAssert solver.addRectangleQuery(
          queryRectangle.xLeft,
          queryRectangle.xRight,
          queryRectangle.yLower,
          queryRectangle.yUpper,
        ) == pairIndex

        solver.addRectangle(
          updateRectangle.xLeft,
          updateRectangle.xRight,
          updateRectangle.yLower,
          updateRectangle.yUpper,
          updateWeight,
        )
      else:
        solver.addRectangle(
          updateRectangle.xLeft,
          updateRectangle.xRight,
          updateRectangle.yLower,
          updateRectangle.yUpper,
          updateWeight,
        )

        doAssert solver.addRectangleQuery(
          queryRectangle.xLeft,
          queryRectangle.xRight,
          queryRectangle.yLower,
          queryRectangle.yUpper,
        ) == pairIndex

    checkAnswers(
      solver.solve(),
      RandomQueryCount +
        scenarioIndex * 8,
      8,
    )

block directedSemantics:
  for scenarioIndex in 0 ..<
      DirectedScenarioCount:
    var initialRectangles =
      newSeq[
        InitialRectangle
      ]()

    initialRectangles.add(
      (
        xLeft:
          -2,
        xRight:
          3,
        yLower:
          -1,
        yUpper:
          4,
        weight:
          signedToMod(
            scenarioIndex + 1
          ),
      )
    )

    initialRectangles.add(
      (
        xLeft:
          0,
        xRight:
          0,
        yLower:
          -3,
        yUpper:
          3,
        weight:
          signedToMod(17),
      )
    )

    var solver =
      initOfflineRectangleAddRectangleSum[
        ModGroup
      ](
        initialRectangles,
        ModGroup,
      )

    doAssert solver.addRectangleQuery(
      -3,
      4,
      -3,
      5,
    ) == 0

    solver.addRectangle(
      1,
      1,
      1,
      5,
      signedToMod(99),
    )

    doAssert solver.addRectangleQuery(
      -3,
      4,
      -3,
      5,
    ) == 1

    solver.addRectangle(
      -1,
      2,
      0,
      3,
      signedToMod(5),
    )

    doAssert solver.addRectangleQuery(
      -2,
      3,
      -1,
      4,
    ) == 2

    solver.addRectangle(
      -1,
      2,
      0,
      3,
      signedToMod(-5),
    )

    doAssert solver.addRectangleQuery(
      -2,
      3,
      -1,
      4,
    ) == 3

    doAssert solver.addRectangleQuery(
      0,
      0,
      -2,
      2,
    ) == 4

    doAssert solver.addRectangleQuery(
      low(int),
      low(int) + 2,
      high(int) - 2,
      high(int),
    ) == 5

    solver.addRectangle(
      low(int),
      low(int) + 2,
      high(int) - 2,
      high(int),
      signedToMod(
        scenarioIndex + 3
      ),
    )

    doAssert solver.addRectangleQuery(
      low(int),
      low(int) + 2,
      high(int) - 2,
      high(int),
    ) == 6

    doAssert solver.addRectangleQuery(
      low(int),
      high(int),
      low(int),
      high(int),
    ) == 7

    let firstSolve =
      solver.solve()

    let secondSolve =
      solver.solve()

    checkAnswers(
      firstSolve,
      RandomQueryCount +
        BoundaryQueryCount +
        scenarioIndex * 8,
      8,
    )

    doAssert firstSolve ==
      secondSolve

block wideSpanDifferential:
  let coordinates = [
    low(int),
    low(int) + 1,
    low(int) + 2,
    -1,
    0,
    1,
    high(int) - 2,
    high(int) - 1,
    high(int),
  ]

  var state =
    20260810'u64

  for scenarioIndex in 0 ..<
      WideScenarioCount:
    var initialRectangles =
      newSeq[
        InitialRectangle
      ]()

    for initialIndex in 0 ..<
        6:
      let rectangle =
        state.nextPoolRectangle(
          coordinates
        )

      initialRectangles.add(
        (
          xLeft:
            rectangle.xLeft,
          xRight:
            rectangle.xRight,
          yLower:
            rectangle.yLower,
          yUpper:
            rectangle.yUpper,
          weight:
            signedToMod(
              state.nextInt(41) - 20
            ),
        )
      )

    var solver =
      initOfflineRectangleAddRectangleSum[
        ModGroup
      ](
        initialRectangles,
        ModGroup,
      )

    for queryIndex in 0 ..<
        8:
      let updateRectangle =
        state.nextPoolRectangle(
          coordinates
        )

      let updateWeight =
        signedToMod(
          state.nextInt(41) - 20
        )

      if queryIndex mod 2 == 0:
        solver.addRectangle(
          updateRectangle.xLeft,
          updateRectangle.xRight,
          updateRectangle.yLower,
          updateRectangle.yUpper,
          updateWeight,
        )

      var queryRectangle:
        Rectangle

      case queryIndex
      of 0:
        queryRectangle =
          sortedRectangle(
            low(int),
            high(int),
            low(int),
            high(int),
          )
      of 1:
        queryRectangle =
          sortedRectangle(
            low(int),
            0,
            low(int),
            0,
          )
      of 2:
        queryRectangle =
          sortedRectangle(
            -1,
            high(int),
            -1,
            high(int),
          )
      else:
        queryRectangle =
          state.nextPoolRectangle(
            coordinates
          )

      doAssert solver.addRectangleQuery(
        queryRectangle.xLeft,
        queryRectangle.xRight,
        queryRectangle.yLower,
        queryRectangle.yUpper,
      ) == queryIndex

      if queryIndex mod 2 == 1:
        solver.addRectangle(
          updateRectangle.xLeft,
          updateRectangle.xRight,
          updateRectangle.yLower,
          updateRectangle.yUpper,
          updateWeight,
        )

    checkAnswers(
      solver.solve(),
      RandomQueryCount +
        BoundaryQueryCount +
        DirectedQueryCount +
        scenarioIndex * 8,
      8,
    )

block emptySolver:
  var initialRectangles =
    newSeq[
      InitialRectangle
    ]()

  var solver =
    initOfflineRectangleAddRectangleSum[
      ModGroup
    ](
      initialRectangles,
      ModGroup,
    )

  doAssert solver.queryCount() ==
    0

  doAssert solver.solve().len ==
    0

block genericBoxGroup:
  type
    Box =
      object
        value:
          uint64

  proc boxAdd(
      a,
      b:
        Box
  ): Box =
    Box(
      value:
        (a.value + b.value) mod 101'u64
    )

  proc boxZero():
      Box =
    Box(
      value:
        0'u64
    )

  proc boxInverse(
      value:
        Box
  ): Box =
    if value.value == 0'u64:
      Box(
        value:
          0'u64
      )
    else:
      Box(
        value:
          101'u64 - value.value
      )

  type
    BoxGroup =
      CommutativeGroupOf(
        Box,
        boxAdd,
        boxZero,
        boxInverse,
      )

    BoxInitialRectangle =
      tuple[
        xLeft, xRight, yLower, yUpper:
          int,
        weight:
          Box
      ]

  var initialRectangles =
    newSeq[
      BoxInitialRectangle
    ]()

  initialRectangles.add(
    (
      xLeft:
        -1,
      xRight:
        2,
      yLower:
        0,
      yUpper:
        4,
      weight:
        Box(
          value:
            3
        ),
    )
  )

  var solver =
    initOfflineRectangleAddRectangleSum[
      BoxGroup
    ](
      initialRectangles,
      BoxGroup,
    )

  doAssert solver.addRectangleQuery(
    -1,
    2,
    0,
    4,
  ) == 0

  solver.addRectangle(
    0,
    1,
    1,
    3,
    boxInverse(
      Box(
        value:
          2'u64
      )
    ),
  )

  doAssert solver.addRectangleQuery(
    -1,
    2,
    0,
    4,
  ) == 1

  let firstSolve =
    solver.solve()

  let secondSolve =
    solver.solve()

  doAssert firstSolve.len ==
    2

  doAssert firstSolve[0].value ==
    36

  doAssert firstSolve[1].value ==
    32

  doAssert firstSolve[0].value ==
    secondSolve[0].value

  doAssert firstSolve[1].value ==
    secondSolve[1].value

echo(
  "OFFLINE_RECTANGLE_ADD_RECTANGLE_SUM_CONTRACT_OK queries=18432 oracle=" &
    OracleSha
)
